var builder = WebApplication.CreateBuilder(args);

// Off by default outside Development. With it on, injecting a scoped
// DbContext into a singleton fails at startup instead of quietly living
// for the lifetime of the process.
builder.Host.UseDefaultServiceProvider((context, options) =>
{
    options.ValidateScopes = true;
    options.ValidateOnBuild = true;
});

// Bound and validated at startup. A missing connection string should stop
// the process here, not appear as a null in the first request.
builder.Services
    .AddOptions<BillingOptions>()
    .Bind(builder.Configuration.GetSection("Billing"))
    .ValidateDataAnnotations()
    .ValidateOnStart();

builder.Services.AddDbContext<AppDbContext>(options =>
    options.UseNpgsql(builder.Configuration.GetConnectionString("Primary")));

var app = builder.Build();

app.MapGet("/orders", async (AppDbContext db, CancellationToken ct) =>
    await db.Orders
        // Not tracked: this is read-only, and tracking every entity costs
        // memory and time for a change that will never be saved.
        .AsNoTracking()
        .Include(o => o.Customer)
        .Include(o => o.Lines)
        // Two collection Includes in one query produce a cartesian product.
        // Split sends one query per collection instead.
        .AsSplitQuery()
        .OrderByDescending(o => o.CreatedAt)
        .Take(50)
        .ToListAsync(ct));

app.Run();
